	["East along the valley road to the quilboar of {area:16677}: the second pylon stands at the eastern end of their camp. A Corpsefeeder (level 45, elite) walks this road: let it pass. The Bristlebacks (levels 42-43) attack on sight; {npc:253527} (level 43, elite) and his bodyguards hold the south side of the camp."] = "Vadi yolu boyunca doğuya, {area:16677} quilboar'larına git: ikinci pylon kamplarının doğu ucunda duruyor. Bu yolda bir Corpsefeeder (45. seviye, elit) yürüyor: geçmesine izin ver. Bristleback'ler (42-43. seviye) görür görmez saldırır. {npc:253527} (43. seviye, elit) ve korumaları kampın güney yakasını tutuyor.",
	["the eastern pylon"] = "doğu pylon'u",

	-- Step 9: The temple of Shen'dralas: the third pylon
	-- {zone:2652} Shen'dralas
	["The temple of {zone:2652}: the third pylon"] = "{zone:2652} tapınağı: üçüncü pylon",
	["South to the Shen'dralar temple at the zone's heart, keeping west of Kog'thug's bodyguards: the third pylon stands inside. The temple's guards are neutral: leave them be."] = "Kog'thug'un korumalarının batısında kalarak güneye, bölgenin ortasındaki Shen'dralar tapınağına git: üçüncü pylon içeride duruyor. Tapınağın muhafızları tarafsız: onlara dokunma.",

	-- Step 10: Evenshade's Overlook
	-- {npc:253471} Mordent Evenshade · {quest:93644} Tattered Journal
	["North-west from the temple to {npc:253471}'s camp on the overlook, beside the spirit healer: the {quest:93644} is his, and he wants to hear about the pylons."] = "Tapınaktan kuzeybatıya, ruh şifacısının yanında, gözetleme yerindeki {npc:253471} kampına git: {quest:93644} onun, pylon'ları da duymak istiyor.",

	-- Step 11: North into Desolace
	-- {npc:253471} Mordent Evenshade · {area:405} Desolace · {area:604} Magram Village
	["{npc:253471} wants a fragment and a shard of the pylons back from {area:405}'s two centaur villages: {area:604} lies just beyond the valley's northern way out.\nCareful: if you have killed Magram or Gelkis centaurs, that clan's guards may attack you when you walk into its village."] = "{npc:253471}, {area:405} bölgesinin iki centaur köyünden pylon'ların bir parçasını ve bir kırığını geri istiyor: {area:604} vadinin kuzey çıkışının hemen ötesinde.\nDikkat: Magram ya da Gelkis centaur'larını öldürdüysen o klanın muhafızları köyüne girdiğinde sana saldırabilir.",

	-- Step 12: Magram Village
	-- {item:255656} Pylon Fragment
	-- plural, as words: Magram Guardians = {npc:255560} Magram Guardian
	["The {item:255656} lies at the western edge of the village; Magram Guardians (levels 39-41) watch over it. They leave you be unless you have fought the Magram: pick the fragment up without a fight. Every Magram you kill turns the clan against you, and back in the valley that means the Necrokhans (level 45, elites) at the western pylon as well."] = "{item:255656} köyün batı kenarında yatıyor, Magram Guardian yaratıkları (39-41. seviye) onu gözlüyor. Magram'larla dövüşmediysen sana bulaşmazlar: parçayı dövüşmeden al. Öldürdüğün her Magram klanı sana karşı çevirir, vadiye dönünce bu batı pylon'undaki Necrokhan'lar (45. seviye, elit) demek.",

	-- Step 13: Gelkis Village
	-- {area:405} Desolace · {area:606} Gelkis Village · {item:255657} Pylon Shard
	-- plural, as words: Gelkis Guardians = {npc:255561} Gelkis Guardian
	["West along {area:405}'s southern edge to {area:606}: the {item:255657} lies at its southern end, watched by Gelkis Guardians (levels 39-41)."] = "{area:405} bölgesinin güney kenarı boyunca batıya, {area:606} köyüne git: {item:255657} güney ucunda yatıyor, Gelkis Guardian yaratıkları (39-41. seviye) onu gözlüyor.",

	-- Step 14: Back into the Valley of Bones
	-- {area:2657} Valley of Bones
	["Back into the {area:2657}"] = "{area:2657} içine geri",
	-- {area:405} Desolace · {area:2657} Valley of Bones · {area:16651} Shen'dralas
	["East again along {area:405}'s southern edge: the {area:2657} opens into {area:16651}."] = "{area:405} bölgesinin güney kenarı boyunca yine doğuya: {area:2657}, {area:16651} içine açılır.",

	-- Step 16: The temple: the Mana Sieve
	-- {item:255662} Mana Sieve
	["The temple: the {item:255662}"] = "Tapınak: {item:255662}",
	-- {npc:253471} Mordent Evenshade · {item:255662} Mana Sieve · {npc:255486} Historian Biraxas · {quest:96018} Powering the Pylons
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift
	["{npc:253471} sends you for the {item:255662}, kept inside the temple beside {npc:255486}. {quest:96018} asks you to gather mana with the Sieve before you repair the pylons: with it in your bags you can handle the Unstable Mana Rifts, the floating sparks of mana all along the road north."] = "{npc:253471} seni tapınağın içinde {npc:255486} yanında saklanan {item:255662} için yollar. {quest:96018}, pylon'ları onarmadan önce Sieve ile mana toplamanı istiyor: çantandayken kuzeye giden yol boyunca süzülen mana kıvılcımları olan Unstable Mana Rift'lerle uğraşabilirsin.",

	-- Step 17: Unstable Mana Rifts: mana for the western pylon
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift
	["Unstable Mana Rifts: mana for the western pylon"] = "Unstable Mana Rift'ler: batı pylon'u için mana",
	-- {item:255662} Mana Sieve
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift · Coalesced Mana Crystals = {item:255667} Coalesced Mana Crystal
	["Use the {item:255662} on the Unstable Mana Rifts, the floating sparks along the road north: each pylon takes four Coalesced Mana Crystals, and the repair uses them up."] = "Kuzeye giden yol boyunca havada süzülen kıvılcımlar olan Unstable Mana Rift'ler üzerinde {item:255662} kullan: her pylon dört Coalesced Mana Crystal ister, onarım da onları tüketir.",
	-- {item:255667} Coalesced Mana Crystal · {item:255662} Mana Sieve
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift
	["{item:255667}, from the Unstable Mana Rifts with the {item:255662}"] = "{item:255667}, {item:255662} ile Unstable Mana Rift'lerden",

	-- Step 18: The road south of the western pylon
	["The road south of the western pylon"] = "Batı pylon'unun güneyindeki yol",
	-- {npc:252711} Decrepit Pylon Protector · {spell:1289727} Repair and Recharge Pylon
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift · Coalesced Mana Crystals = {item:255667} Coalesced Mana Crystal · Magram Necrokhans = {npc:253274} Magram Necrokhan · Nascent Pylon Protectors = {npc:276401} Nascent Pylon Protector
	["North up the road to the first pylon, gathering mana from the Unstable Mana Rifts on the way. Stop where the arrow points, on the road just south of the pylon, keeping to its west edge: the quiet side, with no Protectors behind you. Pull one {npc:252711} at a time down to that spot, the one nearest the pylon's south side first, and kill it there; then step up to the pylon's west side and use the Pile of Pylon Parts Mordent gave you: its {spell:1289727} takes your four Coalesced Mana Crystals.\nCareful: stay off the pylon's east and north-east side. The Protectors stand there two and three together, a Corpsefeeder (level 45, elite) walks among them and the Magram Necrokhans (elites, 45) stand just beyond: nearly every recorded death at this pylon happened east of it. If the Magram attack you (they do once you have killed Magram), wait at the arrow until any Necrokhan by the pylon walks off before you pull. Nascent Pylon Protectors (elites, 43) wander the road south of it: let them pass.\nIf you die here, walk your ghost back to the arrow before you come back to life: players who rose beside the pylon died again within seconds."] = "Yoldaki Unstable Mana Rift'lerden mana toplayarak kuzeye, ilk pylon'a çık. Okun gösterdiği yerde, pylon'un hemen güneyinde yolun batı kenarında dur: arkanda Protector olmayan sakin taraf burası. Her seferinde tek bir {npc:252711} yaratığını (önce pylon'un güney yanına en yakın olanı) o noktaya çekip orada öldür. Sonra pylon'un batı yanına çıkıp Mordent'in verdiği Pile of Pylon Parts'ı kullan: {spell:1289727} büyüsü dört Coalesced Mana Crystal'ını harcar.\nDikkat: pylon'un doğu ve kuzeydoğu yanına gitme. Protector'lar orada ikişer üçer duruyor, aralarında bir Corpsefeeder (45. seviye, elit) yürüyor, Magram Necrokhan yaratıkları (elit, 45) da hemen ötede duruyor: bu pylon'da kayda geçen ölümlerin neredeyse hepsi doğusunda oldu. Magram'lar sana saldırıyorsa (bir Magram öldürdüysen saldırır), çekmeden önce pylon'un yanındaki Necrokhan uzaklaşana kadar okun gösterdiği yerde bekle. Nascent Pylon Protector yaratıkları (elit, 43) güneydeki yolda dolaşıyor: geçmelerini bekle.\nBurada ölürsen dirilmeden önce hayaletini okun gösterdiği yere yürüt: pylon'un yanında dirilen oyuncular birkaç saniye içinde yine öldü.",
	["the road just south of the western pylon"] = "batı pylon'unun hemen güneyindeki yol",

	-- Step 19: The western pylon: repair it
	["The western pylon: repair it"] = "Batı pylon'u: onar",
	-- {item:271882} Pile of Pylon Parts
	["Pull a single Protector down to the road, then use the {item:271882} on the pylon's west side."] = "Tek bir Protector'ı yola çekip pylon'un batı yanında {item:271882} eşyasını kullan.",
	-- {item:271882} Pile of Pylon Parts · {spell:1289727} Repair and Recharge Pylon
	["{item:271882}: {spell:1289727} on the pylon's west side"] = "{item:271882}: pylon'un batı yanında {spell:1289727}",

	-- Step 20: Unstable Mana Rifts: mana for the eastern pylon
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift
	["Unstable Mana Rifts: mana for the eastern pylon"] = "Unstable Mana Rift'ler: doğu pylon'u için mana",
	-- {item:255662} Mana Sieve · {item:271882} Pile of Pylon Parts
	-- plural, as words: Unstable Mana Rifts = {npc:264149} Unstable Mana Rift · Coalesced Mana Crystals = {item:255667} Coalesced Mana Crystal
	["The western repair used up your crystals: on the way east, use the {item:255662} on the Unstable Mana Rifts again for four more Coalesced Mana Crystals. The {item:271882} needs all four for the next repair."] = "Batıdaki onarım kristallerini tüketti: doğuya giderken dört Coalesced Mana Crystal daha için Unstable Mana Rift'ler üzerinde yine {item:255662} kullan. {item:271882} sonraki onarımda dördünü de ister.",

	-- Step 21: Bristleback Retreat: repair the eastern pylon
	-- {area:16677} Bristleback Retreat
	["{area:16677}: repair the eastern pylon"] = "{area:16677}: doğu pylon'unu onar",
	-- {item:271882} Pile of Pylon Parts · {npc:252711} Decrepit Pylon Protector · {npc:253527} Kog'thug the Brave
	-- was: ["East along the valley road to the eastern pylon and repair it the same way, a {npc:252711} first, coming in from the west: {npc:253527} (level 43, elite) and his bodyguards hold the south side of the quilboar camp, and a Corpsefeeder (level 45, elite) walks the road."] = "Nach Osten die Talstraße entlang zum östlichen Pylon und repariere ihn genauso, zuerst einen {npc:252711}, von Westen kommend: {npc:253527} (Stufe 43, Elite) und seine Leibwächter halten die Südseite des Stacheleberlagers, und ein Leichenfresser (Stufe 45, Elite) läuft die Straße entlang."
	["East along the valley road to the eastern pylon and repair it the same way with the {item:271882}, coming in from the west and pulling the nearest {npc:252711} away first: {npc:253527} (level 43, elite) and his bodyguards hold the south side of the quilboar camp, and a Corpsefeeder (level 45, elite) walks the road."] = "Vadi yolu boyunca doğuya, doğu pylon'una git. Batıdan yaklaşıp önce en yakın {npc:252711} yaratığını uzağa çek, sonra pylon'u {item:271882} ile aynı şekilde onar: {npc:253527} (43. seviye, elit) ve korumaları quilboar kampının güney yakasını tutuyor, yolda da bir Corpsefeeder (45. seviye, elit) yürüyor.",
	-- {item:271882} Pile of Pylon Parts · {spell:1289727} Repair and Recharge Pylon
	["{item:271882}: {spell:1289727} on the eastern pylon"] = "{item:271882}: doğu pylon'unda {spell:1289727}",

	-- Step 22: Evenshade's Overlook
	-- {npc:253471} Mordent Evenshade · {quest:93016} A Brief History Lesson
	["Back west along the valley road and south to {npc:253471}. {quest:93016} asks you to hear him out: talk to him once more, then hand it in."] = "Vadi yolu boyunca batıya ve güneye, {npc:253471} yanına dön. {quest:93016} onu dinlemeni istiyor: onunla bir kez daha konuş, sonra teslim et.",
	-- {npc:253471} Mordent Evenshade
	["{npc:253471}: hear him out"] = "{npc:253471}: onu dinle",

	-- Step 23: Liranne
	-- {quest:93568} Partially Digested Collar · {npc:255385} Liranne
	["A Prowler gave up a {quest:93568}: {npc:255385}, north of the temple, knows whose it was."] = "Bir Prowler bir {quest:93568} düşürdü: tapınağın kuzeyindeki {npc:255385} kimin olduğunu biliyor.",

	-- Step 24: The temple: Magister Kirandis
	-- {npc:254656} Magister Kirandis
	["The temple: {npc:254656}"] = "Tapınak: {npc:254656}",
	-- {npc:254656} Magister Kirandis · {npc:254578} Mithera · {quest:93341} Forlorn Gardens
	["{npc:254656} waits inside the temple. Then {npc:254578}, on the temple's eastern side, has work in the {quest:93341}."] = "{npc:254656} tapınağın içinde bekliyor. Sonra tapınağın doğu yakasındaki {npc:254578} adlı NPC'nin {quest:93341} içinde işi var.",

	-- Step 25: The Forlorn Gardens: the pedestal
	-- {quest:93341} Forlorn Gardens
	["The {quest:93341}: the pedestal"] = "{quest:93341}: kaide",
	-- {quest:93341} Forlorn Gardens
	["East of the temple the {quest:93341} have run wild, and their plants attack on sight. Examine the pedestal at the gardens' southern end."] = "Tapınağın doğusunda {quest:93341} yabanileşmiş, bitkileri de görür görmez saldırıyor. Bahçelerin güney ucundaki kaideyi incele.",

	-- Step 27: The Forlorn Gardens
	-- {quest:93341} Forlorn Gardens
	["The {quest:93341}"] = "{quest:93341}",
	-- {npc:254674} Woodwyrd · {area:2100} Maraudon
	-- plural, as words: Rowdy Roses = {npc:254566} Rowdy Rose · Terrible Tulips = {npc:254567} Terrible Tulip · Malevolent Marigolds = {npc:254572} Malevolent Marigold · Nascent Pylon Protectors = {npc:276401} Nascent Pylon Protector
	["Rowdy Roses and Terrible Tulips grow all over the gardens; the Malevolent Marigolds keep to the northern part. {npc:254674}, the treant in the middle of the gardens, has a request of his own that needs water from {area:2100}, a dungeon: this guide leaves it.\nThe Shen'dralar who wander the gardens are neutral, like the temple's guards: leave them be and pull the flowers away from them. Careful: Nascent Pylon Protectors (elites, 43) wander the zone's middle, the gardens too: keep clear of them."] = "Rowdy Rose ve Terrible Tulip yaratıkları bahçelerin her yerinde büyüyor, Malevolent Marigold yaratıkları kuzey kısımda kalıyor. Bahçelerin ortasındaki treant {npc:254674} adlı NPC'nin bir zindan olan {area:2100} suyu isteyen kendi ricası var: bu rehber onu dışarıda bırakır.\nBahçelerde dolaşan Shen'dralar'lar tapınağın muhafızları gibi tarafsız: onlara dokunma ve çiçekleri onlardan uzağa çek. Dikkat: Nascent Pylon Protector yaratıkları (elit, 43) bölgenin ortasında, bahçelerde de dolaşıyor: onlardan uzak dur.",

	-- Step 28: Mithera
	-- {npc:255486} Historian Biraxas · {npc:254656} Magister Kirandis · {npc:252711} Decrepit Pylon Protector
	["{npc:255486}, inside the temple, has a task for you now that you have met {npc:254656}: the heart of a {npc:252711} (42-43, not elite), a short ride back up the road north."] = "Tapınağın içindeki {npc:255486}, {npc:254656} ile tanıştığına göre artık sana bir iş veriyor: kuzeye giden yolda biraz geride bir {npc:252711} (42-43, elit değil) yaratığının kalbi.",

	-- Step 29: A Heart of Crystal
	-- {npc:252711} Decrepit Pylon Protector
	["Use the west face of the western pylon, where you repaired it. Approach on the road from the south and pull one {npc:252711} back to you. Wait for the elite patrols to pass; do not follow a Protector around the east side."] = "Batı pylon'unu onardığın batı yüzünü kullan. Güneyden yolla yaklaşıp tek bir {npc:252711} yaratığını kendine çek. Elit devriyelerin geçmesini bekle, bir Protector'ın peşinden doğu tarafına dolaşma.",

	-- Step 31: Mana Mania
	-- {item:286647} Depleted Crystal Heart · {npc:264149} Unstable Mana Rift · {npc:276401} Nascent Pylon Protector
	["Take the {item:286647} to an {npc:264149} on the road north of the temple and throw it into the rift. The {npc:276401} that comes out is an elite (level 43) but it comes alone: most players in our recordings killed it without a group, from level 41 up."] = "{item:286647} eşyasını tapınağın kuzeyindeki yolda bir {npc:264149} yanına götürüp yarığa at. Çıkan {npc:276401} elit (43. seviye) ama yalnız gelir: oyuncu kayıtlarında çoğu oyuncu onu 41. seviyeden itibaren grupsuz öldürdü.",

	-- Step 32: Shadowprey Village
	-- {zone:2652} Shen'dralas · {area:2657} Valley of Bones · {area:405} Desolace · {area:2408} Shadowprey Village · {area:1637} Orgrimmar · {zone:1444} Feralas · {area:1099} Camp Mojache
	["{zone:2652} is done. Ride back north through the {area:2657} and west along {area:405}'s southern edge to {area:2408} and fly to {area:1637}: the next guide picks up there, with the {zone:1444} guide's hand-ins. Keep your hearthstone (bound at {area:1099}): the next guide uses it to get from {area:1637} back to {area:1099}."] = "{zone:2652} bitti. {area:2657} içinden kuzeye ve {area:405} bölgesinin güney kenarı boyunca batıya, {area:2408} köyüne dönüp {area:1637} şehrine uç: sonraki rehber {zone:1444} rehberinin teslimleriyle orada devam eder. Hearthstone'unu sakla ({area:1099} kampına bağlı): sonraki rehber onunla {area:1637} şehrinden {area:1099} kampına döner.",
	-- {area:2408} Shadowprey Village
	["{area:2408} flight master"] = "{area:2408} uçuş ustası",

	-- Step 33: Back to your route
	["Back to your route"] = "Rotana dön",
	-- {zone:2652} Shen'dralas · {zone:1444} Feralas · {area:2657} Valley of Bones · {area:405} Desolace · {area:1108} Forgotten Coast · {area:1116} Feathermoon Stronghold
	["{zone:2652} is done. Your {zone:1444} guide picks up from here: ride back north through the {area:2657}, west along {area:405}'s southern edge and south into {zone:1444}, to the dock on the {area:1108} where the boat crosses to {area:1116}."] = "{zone:2652} bitti. {zone:1444} rehberin buradan devam eder: {area:2657} içinden kuzeye, {area:405} bölgesinin güney kenarı boyunca batıya ve güneye, {zone:1444} bölgesine, geminin {area:1116} kalesine geçtiği {area:1108} iskelesine dön.",
}
